1	import assert from "node:assert/strict";
2	import { describe, it } from "node:test";
3	
4	import { FixedClock } from "../src/clock.ts";
5	import { DEFAULT_CONFIG } from "../src/config.ts";
6	import { rollup, windowStart, windowsFor } from "../src/rollup.ts";
7	import { MemoryStore } from "../src/store.ts";
8	import { formatSummary, summarize } from "../src/summary.ts";
9	
10	describe("windowStart", () => {
11	  it("aligns down to a multiple of the width", () => {
12	    assert.equal(windowStart(1_234, 1_000), 1_000);
13	    assert.equal(windowStart(1_000, 1_000), 1_000);
14	  });
15	});
16	
17	describe("windowsFor", () => {
18	  it("buckets samples and carries min/max", () => {
19	    const windows = windowsFor(
20	      [
21	        { series: "a", value: 1, at: 0 },
22	        { series: "a", value: 3, at: 500 },
23	        { series: "a", value: 9, at: 1_500 },
24	      ],
25	      1_000,
26	    );
27	    assert.equal(windows.length, 2);
28	    assert.deepEqual(
29	      windows.map((w) => [w.from, w.count, w.min, w.max]),
30	      [
31	        [0, 2, 1, 3],
32	        [1_000, 1, 9, 9],
33	      ],
34	    );
35	  });
36	
37	  it("omits empty windows rather than emitting zeroes", () => {
38	    const windows = windowsFor(
39	      [
40	        { series: "a", value: 1, at: 0 },
41	        { series: "a", value: 1, at: 5_000 },
42	      ],
43	      1_000,
44	    );
45	    assert.deepEqual(
46	      windows.map((w) => w.from),
47	      [0, 5_000],
48	    );
49	  });
50	
51	  it("refuses a zero-width window", () => {
52	    assert.throws(() => windowsFor([], 0), RangeError);
53	  });
54	});
55	
56	describe("rollup", () => {
57	  it("covers the trailing span only", () => {
58	    const store = new MemoryStore(100);
59	    store.put({ series: "a", value: 1, at: 1_000 });
60	    store.put({ series: "a", value: 5, at: 9_000 });
61	
62	    const clock = new FixedClock(10_000);
63	    const windows = rollup(store, "a", 1_000, clock.now(), 2_000);
