import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { MemoryStore } from "../src/store.ts";

describe("MemoryStore construction", () => {
  it("rejects a non-positive-integer maxSeries", () => {
    assert.throws(() => new MemoryStore(10, 0), RangeError);
    assert.throws(() => new MemoryStore(10, -1), RangeError);
    assert.throws(() => new MemoryStore(10, 1.5), RangeError);
  });
});

describe("MemoryStore series cap", () => {
  it("admits up to maxSeries distinct series", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 });
    assert.deepEqual(store.series(), ["a", "b"]);
    assert.equal(store.rejectedSeriesCount(), 0);
  });

  it("rejects a sample for a new series once the cap is hit, leaving existing series untouched", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 });
    store.put({ series: "c", value: 1, at: 0 });

    assert.deepEqual(store.series(), ["a", "b"]);
    assert.equal(store.rejectedSeriesCount(), 1);
  });

  it("keeps accepting samples for an already-tracked series once the cap is hit", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 0 }); // rejected — cap is 1
    store.put({ series: "a", value: 2, at: 1 });

    assert.deepEqual(store.series(), ["a"]);
    assert.deepEqual(
      store.range("a", 0, 2).map((s) => s.value),
      [1, 2],
    );
    assert.equal(store.rejectedSeriesCount(), 1);
  });

  it("frees a slot for a new series once prune() empties a bucket", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 0 });
    store.put({ series: "b", value: 1, at: 100 }); // rejected — cap is 1

    store.prune(50); // drops "a"'s only sample, deleting its bucket
    store.put({ series: "b", value: 1, at: 100 });

    assert.deepEqual(store.series(), ["b"]);
  });
});

