import { ConfigError, DEFAULT_CONFIG, loadConfig } from "../src/config.ts";

describe("loadConfig maxSeries", () => {
  it("defaults when unset", () => {
    const config = loadConfig({});
    assert.equal(config.maxSeries, DEFAULT_CONFIG.maxSeries);
  });

  it("reads a valid override", () => {
    const config = loadConfig({ ROLLUP_MAX_SERIES: "50" });
    assert.equal(config.maxSeries, 50);
  });

  it("fails loud on a present-but-invalid override", () => {
    assert.throws(() => loadConfig({ ROLLUP_MAX_SERIES: "0" }), ConfigError);
    assert.throws(() => loadConfig({ ROLLUP_MAX_SERIES: "not-a-number" }), ConfigError);
  });
});

